{
    String type;
    String title;
    String startsAt;
    String endsAt;
    String world;
    String host;
    String description;
    String codeword;
    String checklist;
    String requiredPlugins;
    String strategyWikiUrl;
    String driveUrl;
    String registrationUrl;
    String registrationEndsAt;
    String youtubeUrl;
    String discordText;
    String clansOne;
    String clansTwo;
    String activity;
    String bossList;
    boolean codewordRequired;
    boolean allowConflict;
}
